export function hasEllipsis(element, axis = "horizontal") {
    if (axis === "horizontal") {
        return element.scrollWidth > element.clientWidth;
    }
    return element.scrollHeight > element.clientHeight;
}
export function hasEllipsisInSubtree(element, axis = "horizontal") {
    if (hasEllipsis(element, axis)) {
        return true;
    }
    return Array.from(element.children).some((child) => child instanceof HTMLElement && hasEllipsisInSubtree(child, axis));
}
